//! Thread titles generated by a provider, as the reference's
//! `ThreadTitleRegenerationService` makes them: the first user message of a
//! thread (or a regenerate request) records `titleRegeneration` and an
//! outbox effect `thread-title.generate`; running the effect asks the text
//! generation model for a title and completes the request with
//! `thread.title.regeneration.complete`.
#[cfg(feature = "native")]
pub(crate) mod branch;
#[cfg(feature = "native")]
pub(crate) mod prompt;
#[cfg(feature = "native")]
pub(crate) mod runner;

use serde_json::{json, Value};

/// A `thread-title.generate` effect to run.
#[derive(Clone, Debug, PartialEq)]
pub struct TitleEffect {
    pub effect_id: String,
    /// The command that asked for the title, which `titleRegeneration`
    /// names.
    pub request_id: String,
    pub thread_id: String,
    /// `{type: "initial", messageId}` or `{type: "regenerate"}`.
    pub kind: Value,
}

impl TitleEffect {
    /// `pendingThreadTitleGenerationEffect`.
    pub fn new(command_id: &str, thread_id: &str, kind: Value) -> Self {
        Self {
            effect_id: format!("effect:{command_id}:thread-title.generate"),
            request_id: command_id.to_owned(),
            thread_id: thread_id.to_owned(),
            kind,
        }
    }

    /// The patch field a commit carries for the shared store's outbox.
    pub fn patch_field(&self) -> Value {
        json!({"commandId": self.request_id, "kind": self.kind})
    }

    /// The effect a commit's patch field names.
    pub fn from_patch(thread_id: &str, field: &Value) -> Option<Self> {
        Some(Self::new(
            field["commandId"].as_str()?,
            thread_id,
            field["kind"].clone(),
        ))
    }

    pub fn request(&self) -> Value {
        json!({"type": "thread-title.generate", "kind": self.kind})
    }
}

/// `isNativeMaintenanceCommand`.
pub(crate) fn is_maintenance_command(message: &Value, text_key: &str) -> bool {
    message["attachments"].as_array().is_none_or(Vec::is_empty)
        && ["/compact", "/logout"].contains(
            &message[text_key]
                .as_str()
                .unwrap_or_default()
                .trim()
                .to_lowercase()
                .as_str(),
        )
}

/// `isPlaceholderThreadTitle`: an agent's numbered placeholder.
fn is_placeholder_title(title: &str) -> bool {
    static PATTERN: std::sync::OnceLock<regex::Regex> = std::sync::OnceLock::new();
    PATTERN
        .get_or_init(|| regex::Regex::new(r" thread \d+$").expect("pattern"))
        .is_match(title)
}

/// `hasTitleSetBeforeFirstMessage`: a title chosen on purpose before the
/// thread's first message, which a generated one does not replace.
fn has_title_set_before_first_message(thread: &Value, seed: Option<&str>) -> bool {
    if thread["titleRenamed"] == true {
        return true;
    }
    let title = thread["title"].as_str().unwrap_or_default().trim();
    thread["forkedFrom"].is_null()
        && thread["lineage"]["sideChat"] != true
        && !title.is_empty()
        && title != "New thread"
        && !is_placeholder_title(title)
        && Some(title) != seed.map(str::trim)
}

/// Whether the `message.dispatch` `command` asks for the thread's first
/// title (the reference orchestrator's rule), given the thread's
/// projection before it: a seeded first message of an untitled thread, or
/// a user's first real message after only maintenance commands.
pub(crate) fn initial_title_requested(projection: &Value, command: &Value) -> bool {
    if is_maintenance_command(command, "text") {
        return false;
    }
    let messages = projection["messages"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let seed = command["titleSeed"]
        .as_str()
        .map(str::trim)
        .filter(|seed| !seed.is_empty());
    let seeds_untitled = seed.is_some()
        && messages.is_empty()
        && !has_title_set_before_first_message(&projection["thread"], seed);
    if seeds_untitled {
        return true;
    }
    if command["createdBy"] != "user" {
        return false;
    }
    let users: Vec<&Value> = messages.iter().filter(|m| m["role"] == "user").collect();
    !users.is_empty() && users.iter().all(|m| is_maintenance_command(m, "text"))
}

/// The thread patch that records a first title request: the seed as the
/// title for now, and `titleRegeneration`.
pub(crate) fn initial_title_patch(command: &Value, effect: &TitleEffect, at: &str) -> Value {
    let mut row = json!({
        "titleRegeneration": {"requestId": effect.request_id, "startedAt": at},
        "updatedAt": at,
    });
    let mut patch = json!({"titleGeneration": effect.patch_field()});
    if let Some(seed) = command["titleSeed"]
        .as_str()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        row["title"] = json!(seed);
        patch["title"] = json!(seed);
    }
    patch["row"] = row;
    patch
}

#[cfg(feature = "native")]
mod service {
    use super::*;
    use std::sync::Arc;

    const MAX_FAILURE_MESSAGE_LENGTH: usize = 300;

    enum Outcome {
        Renamed(String),
        Unchanged,
        Failed(String),
        Stale,
    }

    /// `failureMessage`: the last line of the error's detail, bounded.
    fn failure_message(detail: &str) -> String {
        let Some(last) = detail
            .split('\n')
            .map(str::trim)
            .rfind(|line| !line.is_empty())
        else {
            return "Title generation failed.".into();
        };
        let units: Vec<u16> = last.encode_utf16().collect();
        if units.len() <= MAX_FAILURE_MESSAGE_LENGTH {
            return last.to_owned();
        }
        format!(
            "{}…",
            String::from_utf16_lossy(&units[..MAX_FAILURE_MESSAGE_LENGTH - 1])
        )
    }

    /// The settings as they apply in `project_id`, with its overrides
    /// (`resolveProjectSettings`), for the settings read without a special case.
    pub(crate) fn project_settings(settings: &Value, project_id: &str) -> Value {
        let mut merged = settings.clone();
        if let (Some(target), Some(overrides)) = (
            merged.as_object_mut(),
            settings["projectSettingsOverrides"][project_id].as_object(),
        ) {
            for (key, value) in overrides {
                target.insert(key.clone(), value.clone());
            }
        }
        merged
    }

    /// A project-scoped setting: the project's override when it has one.
    pub(crate) fn project_setting(settings: &Value, project_id: &str, key: &str) -> Value {
        let overridden = &settings["projectSettingsOverrides"][project_id][key];
        if key == "textGenerationModelSelection" && overridden.is_object() {
            let instance = overridden["instanceId"].as_str().unwrap_or_default();
            let generator = settings["textGenerators"].get(instance);
            let enabled = match generator {
                Some(generator) => generator["enabled"] == true,
                None => {
                    crate::orchestration::provider_instance_enabled(settings, project_id, instance)
                }
            };
            if !enabled {
                return settings[key].clone();
            }
        }
        if settings["projectSettingsOverrides"][project_id]
            .get(key)
            .is_some()
        {
            return overridden.clone();
        }
        settings[key].clone()
    }

    async fn attempt(state: &crate::AppState, effect: &TitleEffect) -> Result<Outcome, String> {
        let (projection, project) = {
            let store = state.store.read().await;
            let Some(thread) = store.threads.get(&effect.thread_id) else {
                return Ok(Outcome::Stale);
            };
            let projection = thread.full_projection();
            let project_id = projection["thread"]["projectId"]
                .as_str()
                .unwrap_or_default();
            (
                projection.clone(),
                store.project_rows.get(project_id).cloned(),
            )
        };
        let thread = &projection["thread"];
        if thread["titleRegeneration"]["requestId"] != effect.request_id.as_str() {
            return Ok(Outcome::Stale);
        }
        let Some(project) = project.filter(|p| p["deletedAt"].is_null()) else {
            return Ok(Outcome::Failed(
                "This thread's project no longer exists.".into(),
            ));
        };
        let messages = projection["messages"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        let (message, attachments) = if effect.kind["type"] == "initial" {
            match messages
                .iter()
                .find(|m| m["id"] == effect.kind["messageId"] && m["streaming"] != true)
            {
                None => (String::new(), Vec::new()),
                Some(m) => {
                    let text = m["text"].as_str().unwrap_or_default();
                    (
                        if prompt::is_attachment_only_bootstrap_prompt(text) {
                            String::new()
                        } else {
                            text.to_owned()
                        },
                        m["attachments"].as_array().cloned().unwrap_or_default(),
                    )
                }
            }
        } else {
            let title_messages: Vec<prompt::TitleMessage> = messages
                .iter()
                .filter(|m| {
                    (m["role"] == "user" || m["role"] == "assistant") && m["streaming"] != true
                })
                .map(|m| prompt::TitleMessage {
                    role: m["role"].as_str().unwrap_or_default().to_owned(),
                    text: m["text"].as_str().unwrap_or_default().to_owned(),
                    attachments: m["attachments"].as_array().cloned().unwrap_or_default(),
                })
                .collect();
            prompt::format_thread_title_context(&title_messages)
        };
        if message.is_empty() && attachments.is_empty() {
            return Ok(Outcome::Failed(
                "This thread has no messages to title yet.".into(),
            ));
        }
        let settings = state.settings.internal().map_err(|e| e.to_string())?;
        let project_id = thread["projectId"].as_str().unwrap_or_default();
        let selection = project_setting(&settings, project_id, "textGenerationModelSelection");
        let instructions = project_setting(&settings, project_id, "threadTitleInstructions");
        let worktree = thread["worktreePath"]
            .as_str()
            .filter(|path| std::path::Path::new(path).exists());
        let cwd = worktree
            .or(project["workspaceRoot"].as_str())
            .unwrap_or_default()
            .to_owned();
        let previous = thread["title"].as_str().unwrap_or_default().to_owned();
        let prompt_text = prompt::build_thread_title_prompt(&prompt::TitlePromptInput {
            message: &message,
            linked_context: None,
            project_title: project["title"].as_str(),
            previous_title: (effect.kind["type"] == "regenerate").then_some(previous.as_str()),
            fork_source: None,
            attachments: &attachments,
            instructions: instructions.as_str(),
        });
        let title = runner::generate_thread_title(
            state,
            &settings,
            runner::Request {
                cwd: &cwd,
                prompt: &prompt_text,
                attachments: &attachments,
                selection,
                project_id,
                output: runner::OutputKind::Title,
            },
        )
        .await?;
        let generated = title.trim();
        Ok(
            if generated == "New thread"
                || (effect.kind["type"] == "regenerate" && generated == previous.trim())
            {
                Outcome::Unchanged
            } else {
                Outcome::Renamed(title)
            },
        )
    }

    /// Run `effect` to its end: generate the title (an initial title tries
    /// three times), complete the request, and settle the outbox row.
    pub async fn execute(state: Arc<crate::AppState>, effect: TitleEffect) {
        let retries = if effect.kind["type"] == "initial" {
            2
        } else {
            0
        };
        let mut delay = std::time::Duration::from_secs(2);
        let mut tries = 0;
        let outcome = loop {
            match attempt(&state, &effect).await {
                Ok(outcome) => break outcome,
                Err(detail) if tries >= retries => {
                    tracing::warn!(thread_id = %effect.thread_id, request_id = %effect.request_id,
                        "Thread title generation failed");
                    break Outcome::Failed(failure_message(&detail));
                }
                Err(_) => {
                    tries += 1;
                    tokio::time::sleep(delay).await;
                    delay *= 2;
                }
            }
        };
        if !matches!(outcome, Outcome::Stale) {
            let regenerate = effect.kind["type"] == "regenerate";
            let mut command = json!({
                "type": "thread.title.regeneration.complete",
                "commandId": format!("{}:title-complete", effect.request_id),
                "threadId": effect.thread_id,
                "requestId": effect.request_id,
            });
            if let Outcome::Renamed(title) = &outcome {
                command["title"] = json!(title);
            }
            if regenerate {
                command["outcome"] = match &outcome {
                    Outcome::Renamed(_) => json!({"status": "renamed"}),
                    Outcome::Unchanged => json!({"status": "unchanged"}),
                    Outcome::Failed(message) => json!({"status": "failed", "message": message}),
                    Outcome::Stale => Value::Null,
                };
            }
            if let Err(error) = crate::dispatch_orchestration_command(state.clone(), command).await
            {
                tracing::warn!(?error, "could not complete a thread title request");
            }
        }
        state.settle_effect(&effect.effect_id, "succeeded").await;
    }
}

#[cfg(feature = "native")]
pub use service::execute;
#[cfg(feature = "native")]
pub(crate) use service::{project_setting, project_settings};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_seeded_first_message_asks_for_a_title_unless_the_thread_was_named() {
        let empty = json!({"thread": {"title": "New thread", "forkedFrom": null, "lineage": {}}, "messages": []});
        let command = json!({"text": "fix login", "titleSeed": "fix login", "createdBy": "user"});
        assert!(initial_title_requested(&empty, &command));
        let named = json!({"thread": {"title": "Issue 12", "forkedFrom": null, "lineage": {}}, "messages": []});
        assert!(!initial_title_requested(&named, &command));
        assert!(!initial_title_requested(
            &empty,
            &json!({"text": "/compact", "titleSeed": "x", "attachments": []})
        ));
        let compacted = json!({"thread": {"title": "t"}, "messages": [{"role": "user", "text": "/compact", "attachments": []}]});
        assert!(initial_title_requested(
            &compacted,
            &json!({"text": "now work", "createdBy": "user"})
        ));
        assert!(!initial_title_requested(
            &empty,
            &json!({"text": "now work", "createdBy": "user"})
        ));
    }
}
